mapper.select:
SELECT bbp.billId, bbp.billPayId, DATE_FORMAT(bbp.orderDate, '%Y-%m-%d') AS orderDate, DATE_FORMAT(bbp.billDate, '%Y-%m-%d') AS billDate, bbp.billNum, bbp.orgId, bbp.orgName, bbp.patientId, bbp.patientName, bbp.mobile, bbp.age, DATE_FORMAT(bbp.payeeDate, '%Y-%m-%d %H:%i') AS chargeDate, bbp.receivedAmount AS receivedWorkload FROM ( SELECT bbp.bill_pay_id as billPayId, bbp.received_amount AS receivedAmount, bbp.bill_id AS billId, bbp.pay_date AS payeeDate, bb.org_id AS orgId, bb.abbreviation AS orgName, bb.patient_id AS patientId, bb.order_date AS orderDate, bb.bill_date AS billDate, bb.bill_num AS billNum, bb.patientName, bb.pinyinName, bb.age, bb.mobile FROM ( SELECT bill_id, bill_pay_id, pay_date, SUM(received_amount) AS received_amount FROM base_bill_pay_share
AND executor_id = #{query.employeeId}
AND DATE_FORMAT(pay_date, '%Y-%m-%d' ) >= #{query.startDate}
AND DATE_FORMAT(pay_date, '%Y-%m-%d' ) <= #{query.endDate}
AND DATE_FORMAT(pay_date, '%Y-%m' ) >= #{query.startDate}
AND DATE_FORMAT(pay_date, '%Y-%m' ) <= #{query.endDate}
AND DATE_FORMAT(pay_date, '%Y' ) >= #{query.startDate}
AND DATE_FORMAT(pay_date, '%Y' ) <= #{query.endDate}
GROUP BY bill_id, bill_pay_id, pay_date ) bbp INNER JOIN ( SELECT bb.org_id, bo.abbreviation, bb.patient_id, bb.bill_id, bb.order_date, bb.bill_date, bb.bill_num, bp.`name` AS patientName, bp.pinyin_name AS pinyinName, TIMESTAMPDIFF(YEAR, bp.birthday,CURDATE()) AS age, bp.mobile AS mobile FROM base_bill bb LEFT JOIN base_organization bo ON bb.org_id = bo.org_id LEFT JOIN base_patient bp ON bb.patient_id = bp.patient_id
AND bb.actual_amount > 0
AND bb.org_id = #{query.orgId}
) bb ON bbp.bill_id = bb.bill_id
AND bbp.received_amount > 0
) bbp
AND concat(IFNULL(bbp.patientName, ''), IFNULL(bbp.pinyinName, ''), IFNULL(bbp.mobile, '')) Like concat('%', #{query.keyword}, '%')
AND bbp.billNum LIKE concat('%', #{query.billNum} ,'%')
AND DATE_FORMAT(bbp.billDate, '%Y-%m-%d') = #{query.billDate}
GROUP BY bbp.billPayId ORDER BY bbp.billDate DESC, bbp.billNum DESC
